def forward(groups):
    speeds = []
    for g in groups:
        if g.isdigit():
            speeds.append(int(g))
        elif g == '****':
            speeds.append(-1)
        else:
            raise ValueError(f"Unexpected group value: {g}")
    return {'stored': speeds, 'layout': []}

def inverse(record):
    speeds = [str(s) if s != -1 else '****' for s in record['stored']]
    return '({})'.format(' '.join(speeds))
